  &reftitle.description;

   stringhtmlentities
   stringstring
   intflagsENT_QUOTES | ENT_SUBSTITUTE | ENT_HTML401
   stringnullencoding&null;
   booldouble_encode&true;


यो function सबै दृष्टिकोणले htmlspecialchars सँग समान छ, बाहेक htmlentities मा, HTML character entity सरहका सबै characters लाई ती entities मा translate गरिन्छ। प्रदान गरिएका flags constants मा आधारित भएर प्रयोग गरिएको translation table return गर्नका लागि get_html_translation_table function प्रयोग गर्न सकिन्छ।

यदि तपाईँ यसको सट्टा decode गर्न चाहनुहुन्छ भने (यसको विपरित), तपाईँ html_entity_decode प्रयोग गर्न सक्नुहुन्छ।

  &reftitle.returnvalues;

Encode गरिएको string return गर्दछ।

यदि input string मा दिइएको encoding भित्र invalid code unit sequence समावेश छ भने, ENT_IGNORE वा ENT_SUBSTITUTE flags सेट गरिएको अवस्थामा बाहेक खाली string return हुनेछ।

&reftitle.changelog;





    &Version;
    &Description;





    8.1.0
    flags लाई from ENT_COMPAT बाट ENT_QUOTES | ENT_SUBSTITUTE | ENT_HTML401 मा परिवर्तन गरियो।



    8.0.0
    encoding अब nullable भएको छ।

  &reftitle.examples;



    एउटा htmlentities उदाहरण


<?php
$str = "A 'quote' is <b>bold</b>";

echo htmlentities($str);
echo "\n\n";
echo htmlentities($str, ENT_COMPAT);
?>


    &example.outputs;


A &#039;quote&#039; is &lt;b&gt;bold&lt;/b&gt;

A 'quote' is &lt;b&gt;bold&lt;/b&gt;








    ENT_IGNORE को प्रयोग


<?php
$str = "\x8F!!!";

// Outputs an empty string
echo htmlentities($str, ENT_QUOTES, "UTF-8");

// Outputs "!!!"
echo htmlentities($str, ENT_QUOTES | ENT_IGNORE, "UTF-8");
?>
